#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib
BASE=Path(__file__).resolve().parent;REPO=BASE.parents[5]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
p=BASE/'run-attempt-1/result.json';r=json.loads(p.read_text());lock=json.loads((BASE/'source-lock.json').read_text());block=lock['blocks'][0]
assert r['passed'] and len(r['commands'])==48 and all(c['exit_code']==0 for c in r['commands'])
assert r['driver_sha256']==sha(BASE/'replay.py') and r['source_lock_sha256']==sha(BASE/'source-lock.json')
assert r['lean_sha256']=='1b370cfcbf44e80d1b004ab1b1ab9a4c73951f9f7c242140bcff9bc577576554'
assert all(x['passed'] for k in ['dependencies_before','dependencies_after','original25_before','original25_after'] for x in r[k])
for record in block['records']:assert sha(REPO/record['path'])==record['sha256']
assert all(r['source_unchanged_after'].values()) and all(r['author_locks_unchanged_after'].values())
for c in r['commands']:assert sha(BASE/'run-attempt-1'/c['log'])==c['log_sha256']
approval={'passed':True,'approval':'APPROVED_FROZEN_STRICT_MATHEMATICS_ONLY','reviewer':'/root/recover_verification','proof_source_authorship':[],'review_recorded_utc':datetime.now(timezone.utc).isoformat(),'execution_started_utc':r['started_utc'],'execution_finished_utc':r['finished_utc'],'scope':'Six frozen TTStrict modules, fresh full47-source closure plus literal consumer.','source_review':['FirstFrames contains only finite actual matrices, positive count, bounded width and orthonormality. It assumes no approximation or runtime correctness.','For each arbitrary supplied ValidSVD, a finite frame family is fixed before any comparator and every child Completion family. The default zero-tail case and positive-threshold tie case cover every rank allowance satisfying the stated positive rank hypothesis.','Each candidate has actual first tail error. The projected-child estimate holds for every actual Completion response, and the strict case separates a strictly smaller first error from equality with strictly contracting residual. Shape order≥3 supplies the positive remaining-mode factor.','Every actual minimum of the finite candidate errors is feasible and satisfies the strict bound for every positive-error feasible comparator, and exact equality when comparator error is zero. Minimum existence is separately proved from the finite nonempty family.','Original input/output equivalences preserve exact entries, ranks and FrobeniusSq. first_svd_strict_family uses the original immutable Feasible and actual sInf Optimum with its separately proved attainment, and factor ((S.order : ℝ) - 1). Its first SVD and all child response choices remain universal.'],'limits':'The finite family and minimum are mathematical constructions using permitted classical choice. Explicit cyclic frame computation, memory layout, uniform finite RAM program, proof for every complete machine execution and polynomial total CostThrough remain separate obligations. This is not a proof of the full original machine Target, and it carries no Linux or Comparator acceptance claim.','author_source_lock':{'path':block['author_lock_path'],'sha256':block['author_lock_sha256']},'independent_source_lock_sha256':sha(BASE/'source-lock.json'),'result':{'path':str(p.relative_to(REPO)),'sha256':sha(p)},'scoped_kernel_result':r['blocks']['strict_tensor_math'],'literal_consumer_bindings':r['consumer_bindings']['strict_tensor_math'],'kernel_mode':'LeanCert kernel','axioms':r['blocks']['strict_tensor_math']['observed_axioms'],'project_objects_reused':False,'ten_exact_clean_pins_before_after':True,'original25_byte_exact_against_2b_before_after':True,'private_or_local_explicit_declarations':[],'generated_or_anonymous_helpers':'All47 sources are kernel compiled and every explicit named declaration is individually kind/trust/axiom checked; anonymous and generated helper constants are covered by compilation and transitive dependencies, not claimed as separate source-name assertions.','proof_sources_changed':False,'full_TR04_Target_proved':False,'authoritative_Linux_Comparator':False}
q=BASE/'APPROVAL.json';q.write_text(json.dumps(approval,indent=2)+'\n');print(json.dumps({'path':str(q.relative_to(REPO)),'sha256':sha(q),'result_sha256':sha(p),'passed':True},indent=2))
